import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float, color, normalView, positionViewDirection, dot, pow, sub, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, CylinderGeometry, OctahedronGeometry, PlaneGeometry, CircleGeometry, DirectionalLight, PointLight, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const SURFACE = colors.surface ?? '#101017';
  const INK = colors.ink ?? '#16161d';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';
  const COOL = '#9fb0c4'; // spec-named dispersed stop / rim hue

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---------------------------------------------------------------
  // STAGE: gradient backdrop plane (7 x 6 at z = -2.5)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    const c0 = color(BG);
    const c1 = color('#12121a');
    const c2 = color(INK);
    const lower = mix(c0, c1, smoothstep(float(0.0), float(0.6), v));
    backdropMat.colorNode = mix(lower, c2, smoothstep(float(0.6), float(1.0), v));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // LIGHTS: cool back rim from behind-left + faint accent glow
  // (scene supplies ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(COOL, 1.4);
  rim.position.set(-3.2, 1.6, -4.0);
  rim.target.position.set(0, 0.2, 0);
  group.add(rim);
  group.add(rim.target);

  const coreGlow = new PointLight(ACCENT, 1.1, 4.5, 2);
  coreGlow.position.set(0, 0.2, 0);
  group.add(coreGlow);

  // ---------------------------------------------------------------
  // PRISM: equilateral triangular cross-section, side 1.2, length 1.8
  // ---------------------------------------------------------------
  const prismGroup = new Group();
  prismGroup.position.set(0, 0.2, 0);
  group.add(prismGroup);

  const circumradius = 1.2 / Math.sqrt(3); // equilateral side 1.2
  const prismGeo = new CylinderGeometry(circumradius, circumradius, 1.8, 3, 1, false);
  prismGeo.rotateZ(Math.PI / 2); // axis horizontal (X)

  const prismMat = new MeshPhysicalNodeMaterial({
    color: 0xffffff,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    metalness: 0.0,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    transparent: true,
    side: DoubleSide
  });
  prismMat.dispersion = 0.18; // RGB refraction split
  prismMat.attenuationColor = new ctx.THREE.Color(PAPER);
  prismMat.attenuationDistance = 2.5;

  // TSL dispersion edge pass: fresnel rim splits accent -> paper -> cool
  {
    const fres = pow(sub(float(1.0), dot(normalView, positionViewDirection).abs()), float(3.0));
    const dispersed = mix(
      mix(color(ACCENT), color(PAPER), smoothstep(float(0.2), float(0.5), uv().x)),
      color(COOL),
      smoothstep(float(0.5), float(0.8), uv().x)
    );
    prismMat.emissiveNode = dispersed.mul(fres).mul(float(0.55));
  }

  const prism = new Mesh(prismGeo, prismMat);
  prism.rotation.z = (12 * Math.PI) / 180;
  prism.rotation.y = (20 * Math.PI) / 180;
  prismGroup.add(prism);
  disposables.push(prismGeo, prismMat);

  // ---------------------------------------------------------------
  // EMISSIVE CORE: octahedron inside prism (the single brightest element)
  // ---------------------------------------------------------------
  const coreGeo = new OctahedronGeometry(0.35, 0);
  const coreMat = new MeshStandardNodeMaterial({
    color: ACCENT,
    emissive: ACCENT,
    emissiveIntensity: 2.2,
    roughness: 0.4,
    metalness: 0.1
  });
  const core = new Mesh(coreGeo, coreMat);
  prismGroup.add(core);
  disposables.push(coreGeo, coreMat);

  // ---------------------------------------------------------------
  // CAUSTIC STREAK: 2.4 x 0.5 floor plane at y = -1.1, dispersed gradient
  // ---------------------------------------------------------------
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const x = uv().x;
    const grad = mix(
      mix(color(ACCENT), color(PAPER), smoothstep(float(0.2), float(0.5), x)),
      color(COOL),
      smoothstep(float(0.5), float(0.8), x)
    );
    causticMat.colorNode = grad;
    const edgeX = smoothstep(float(0.0), float(0.15), x).mul(sub(float(1.0), smoothstep(float(0.85), float(1.0), x)));
    const edgeY = smoothstep(float(0.0), float(0.25), uv().y).mul(sub(float(1.0), smoothstep(float(0.75), float(1.0), uv().y)));
    causticMat.opacityNode = edgeX.mul(edgeY).mul(float(0.35));
  }
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0.3);
  group.add(caustic);
  disposables.push(causticGeo, causticMat);

  // Contact shadow under prism
  const shadowGeo = new CircleGeometry(1.15, 48);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = sub(float(1.0), smoothstep(float(0.15), float(0.5), length(uv().sub(0.5)))).mul(float(0.5));
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.11, 0.1);
  group.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // TEXT: verbatim from spec textContent
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let yCursor = -1.75; // headline baseline 1.75 below center
  for (const item of items) {
    const isHeadline = item.role === 'headline';
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? (isHeadline ? 68 : 18),
      color: isHeadline ? PAPER : COOL,
      align: 'center',
      letterSpacingPx: isHeadline ? -0.3 : 1.4
    });
    t.position.set(0, isHeadline ? -1.75 : yCursor - 0.5, 0.4);
    if (!isHeadline) yCursor -= 0.5;
    group.add(t);
  }

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (from config, never inlined)
  // ---------------------------------------------------------------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[p.name];
    if (fn) primitiveHandles.push(fn(prismGroup, p.params ?? {}));
  }

  // ---------------------------------------------------------------
  // MOTION: rise-in entrance + weighted settle; idle = slow core spin
  // ---------------------------------------------------------------
  const entrance = gsap.timeline();
  entrance.from(prismGroup.position, { y: prismGroup.position.y - 0.35, duration: 0.7, ease: 'power3.out' });
  entrance.fromTo(
    prismGroup.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' },
    0
  );
  entrance.to(prismGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.35);
  timelines.push(entrance);

  const idle = gsap.to(core.rotation, { y: Math.PI * 2, duration: 14, repeat: -1, ease: 'none' });
  timelines.push(idle);

  // ---------------------------------------------------------------
  // INTERACTION: caustic elongates 8% on hover tilt, settles on release
  // ---------------------------------------------------------------
  group.userData.handlers = {
    pointerover: () => {
      gsap.to(caustic.scale, { x: 1.08, duration: 0.35, ease: 'power2.out' });
    },
    pointerout: () => {
      gsap.to(caustic.scale, { x: 1.04, duration: 0.2, ease: 'power2.out', onComplete: () => {
        gsap.to(caustic.scale, { x: 1.0, duration: 0.9, ease: 'power4.out' });
      } });
    }
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(caustic.scale);
    gsap.killTweensOf(prismGroup.scale);
    gsap.killTweensOf(prismGroup.position);
    for (const h of primitiveHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
  };

  return group;
}
